// Ny oversikt og nye regler har hver sin flate. Milepælmerket er avledet, ikke en ny regeltype.
const oldRulesView=rulesView;
let moduleArea='template',settingsTab='admins',categoryFilter=['Budsjett','Gulbok','Regnskap'],roleFilter='all',sortOrder='chronological',sortYear=2026,embedded=new URLSearchParams(location.search).get('embedded')==='1',initialized=!embedded;
let people=[{id:'self',name:'Du · eksempeladministrator',admin:true,source:'manual',current:true},{id:'sbr',name:'Eksempeladministrator SBR',admin:true,source:'entra'},{id:'fa1',name:'Eksempelbruker FA',admin:false,source:'manual'},{id:'fa2',name:'Eksempelbruker FIN',admin:false,source:'manual'}];
rules.push({...defaults(),title:'Etterkontroll av avklaringer',loop:'etterkontroll',kind:'relative',anchor:'avklaringer',days:2,direction:1,category:'Gulbok'});
NAV[1][2]='Eksisterende og nye gjentaksregler, prøveberegning og overføring av mal. Konkrete frister behandles under det aktuelle budsjettåret.';
NAV.push(['settings','Administrator-innstillinger','Administratortilganger og felles faseinndeling. Andre felles innstillinger kan samles her.']);
tab='list';
function dependents(r){if(rules.find(x=>x.loop===r.loop)?.id!==r.id)return [];return rules.filter(x=>x.kind==='relative'&&x.anchor===r.loop)}
function allDependents(r){const seen=new Set([r.id]),result=[];function visit(x){for(const child of dependents(x)){if(seen.has(child.id))continue;seen.add(child.id);result.push(child);visit(child)}}visit(r);return result}
function role(r){return r.kind==='relative'?'dependent':dependents(r).length?'milestone':'independent'}
function roleMarkup(r){const kind=role(r);return kind==='milestone'?'<span class="rule-role root"><span class="milestone-icon" aria-hidden="true">⚑</span>Milepæl</span>':kind==='dependent'?'<span class="rule-role dependent"><span aria-hidden="true">↳</span> Avhengig</span>':'<span class="rule-role">Selvstendig</span>'}
function sortDate(r){const result=calc(r,sortYear);if(result.error||!result.date)return null;return result.tentative?iso(result.date).slice(0,7)+'-01':iso(result.date)}
function filteredRules(){const found=rules.filter(r=>categoryFilter.includes(r.category)&&(roleFilter==='all'||role(r)===roleFilter)&&(r.title+' '+r.loop+' '+sentence(r)).toLocaleLowerCase('nb').includes(search.toLocaleLowerCase('nb')));const cache=new Map(found.map(r=>[r.id,sortDate(r)]));return found.sort((a,b)=>{const title=(a.title||a.loop).localeCompare(b.title||b.loop,'nb')||rules.indexOf(a)-rules.indexOf(b);if(sortOrder==='title')return title;const ad=cache.get(a.id),bd=cache.get(b.id);if(ad===null&&bd!==null)return 1;if(ad!==null&&bd===null)return -1;if(ad===null)return title;return (sortOrder==='reverse'?-1:1)*ad.localeCompare(bd)||title})}

render=function(){const active=document.activeElement,restore=active?.id?'#'+CSS.escape(active.id):active?.dataset.tab?'[data-tab="'+active.dataset.tab+'"]':null;if($('anchorDetails'))anchorOpen=$('anchorDetails').open;
 $('adminNav').innerHTML=NAV.map(([key,name])=>`<button type="button" class="side-button ${key===moduleArea?'active':''}" ${key===moduleArea?'aria-current="page"':''} data-nav="${key}">${name}</button>`).join('');
 const settings=moduleArea==='settings';$('content').innerHTML=`<div class="heading"><div><p class="eyebrow">Administrasjon · ${settings?'felles innstillinger':'felles regler'}</p><h1>${settings?'Administrator-innstillinger':'Årsmal'}</h1><p class="lead">${settings?'Tilganger og felles innstillinger for løsningen.':'Vedlikehold reglene, og se hvilke frister som følger milepælene.'}</p></div><span class="example-badge">Eksempeldata</span></div>${settings?settingsView():templateView()}`;
 if(!settings&&['new','edit'].includes(tab))updateLive();if(restore)document.querySelector(restore)?.focus({preventScroll:true});postState();};
function templateView(){return `<nav class="tabs" aria-label="Årsmalens områder">${[['list','Eksisterende gjentaksregler'],['new','Nye gjentaksregler'],['try','Prøv malen'],['transfer','Overfør mal']].map(([key,title])=>`<button type="button" class="${key==='new'?'new-tab':''}" data-tab="${key}" aria-pressed="${tab===key||key==='list'&&tab==='edit'}">${title}</button>`).join('')}</nav>${tab==='list'?registerView():['new','edit'].includes(tab)?editorView():tab==='try'?tryView():transferView()}`}
function registerView(){const count=k=>rules.filter(r=>role(r)===k).length;return `<div class="rules-summary"><div><strong>${count('milestone')}</strong><span>Selvstendige milepæler</span></div><div><strong>${count('independent')}</strong><span>Andre selvstendige regler</span></div><div><strong>${count('dependent')}</strong><span>Avhengige regler</span></div></div><section class="surface filter-box"><div class="rule-filters">${field('Søk i regler','registerSearch',search,'search')}${select('Sammenheng','roleFilter',[['all','Alle regler'],['milestone','Milepæler (selvstendige)'],['independent','Andre selvstendige regler'],['dependent','Avhengige regler']],roleFilter)}<fieldset class="filter-categories"><legend>Kategori</legend>${[['Budsjett','Budsjett'],['Gulbok','Gul bok'],['Regnskap','Regnskap']].map(([key,label])=>`<label><input type="checkbox" name="categoryFilter" value="${key}" ${categoryFilter.includes(key)?'checked':''}>${label}</label>`).join('')}</fieldset></div><div class="sorting-row">${select('Sorter listen','sortOrder',[['chronological','Kronologisk – tidligst først'],['reverse','Kronologisk – senest først'],['title','Tittel – A til Å']],sortOrder)}${field('Beregn datoer for budsjettår','sortYear',sortYear,'number','min="1" max="9999"')}<p>Rekkefølgen følger beregnede kalenderdatoer for valgt budsjettår, også før og etter selve året. Tentative frister plasseres etter måned. Regler som ikke kan beregnes, står sist.</p></div><div class="rule-countline"><span id="resultCount"></span><button type="button" class="text-button" data-list-action="resetFilters">Nullstill filtre</button></div></section><section class="surface table-panel"><div class="table-scroll"><table class="rule-register"><thead><tr><th>Regel</th><th>Kategori</th><th>Sammenheng</th><th>Dato bestemmes av</th><th>Handling</th></tr></thead><tbody id="registeredRules"></tbody></table></div></section><p class="role-explanation">⚑ <strong>Milepæl</strong> er en selvstendig regel som andre regler avhenger av. En regel som selv avhenger av en milepæl, står som <strong>Avhengig</strong> også når flere regler bygger videre på den. Merket og filteret endrer ikke beregningen.</p>`}
function updateRegister(){if(!$('registeredRules'))return;const found=filteredRules();$('resultCount').textContent=`Viser ${found.length} av ${rules.length} regler`;$('registeredRules').innerHTML=found.map(r=>{const deps=dependents(r),total=allDependents(r).length,anchor=r.kind==='relative'?rules.find(a=>a.loop===r.anchor):null;return `<tr data-rule-row="${r.id}"><td><strong>${esc(r.title||r.loop)}</strong><small>${esc(TYPES.find(t=>t[0]===r.kind)?.[1])}${r.election?' · valgår':''}</small></td><td>${r.category==='Gulbok'?'Gul bok':esc(r.category)}</td><td>${roleMarkup(r)}${deps.length?`<small>${total} avhengige totalt · ${deps.length} direkte</small>`:''}</td><td><div class="rule-sort-date">${resultMarkup(calc(r,sortYear))}</div>${esc(sentence(r))}${r.kind==='relative'?`<small>${anchor?'Milepæl: '+esc(anchor.title||anchor.loop):'Manuelt anker: '+esc(r.anchor)}</small>`:''}${deps.length||r.kind==='relative'?`<button type="button" class="connections-link" data-connections="${r.id}">Se sammenhengen</button>`:''}</td><td><div class="row-actions"><button type="button" data-edit="${r.id}">Rediger</button><button type="button" data-preview-rule="${r.id}">Se datoer</button></div></td></tr>`}).join('')||'<tr><td colspan="5"><div class="template-empty">Ingen regler passer med filtrene. Juster utvalget eller nullstill filtrene.</div></td></tr>'}
function editorView(){const markup=oldRulesView(),start=markup.indexOf('<section class="editor">');return `<button type="button" class="back-to-list" data-tab="list">← Til eksisterende regler</button>`+markup.slice(start,-6).replace('<section class="editor">','<section class="editor standalone">')}
selectDraft=function(id){selected=id;draft=id?clone(rules.find(r=>r.id===id)):defaults();dirty=false;tab=id?'edit':'new';render()};
guardTab=function(next){const go=()=>{dirty=false;if(next==='new'){selected=null;draft=defaults()}else if(next!=='edit')draft=selected&&rules.some(r=>r.id===selected)?clone(rules.find(r=>r.id===selected)):defaults();tab=next;render()};if(dirty)confirmAction('Forlate regelutkastet?','Du har endringer som ikke er lagret. Vil du forkaste dem og gå videre?','Forkast og gå videre',go);else go()};
function settingsView(){return `<nav class="tabs" aria-label="Innstillingsområder"><button type="button" data-setting-tab="admins" aria-pressed="${settingsTab==='admins'}">Administratorer</button><button type="button" data-setting-tab="phases" aria-pressed="${settingsTab==='phases'}">Faseinndeling</button></nav>${settingsTab==='phases'?phaseView():adminsView()}`}
function adminsView(){return `<div class="settings-info">Skisse av ny funksjon for manuell utnevnelse og fjerning. Her endres bare eksempelpersoner. Dagens Entra-styrte tilgang videreføres og forvaltes gjennom Entra.</div><section class="surface"><div class="settings-actions"><h2>Administratorer</h2><button type="button" class="primary" data-admin-action="appoint">+ Utnevn administrator</button></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>Person</th><th>Tilgangskilde</th><th>Handling</th></tr></thead><tbody>${people.filter(p=>p.admin).map(p=>`<tr><td><strong>${esc(p.name)}</strong>${p.current?'<small>Din bruker i skissen</small>':''}</td><td><span class="tag">${p.source==='entra'?'Entra-gruppe':'Manuelt tildelt'}</span></td><td>${p.current?'<span class="hint">Din tilgang</span>':p.source==='entra'?'<span class="hint">Forvaltes i Entra</span>':`<button type="button" data-admin-remove="${p.id}">Fjern administratortilgang</button>`}</td></tr>`).join('')}</tbody></table></div><p class="preview-help">Dette gjelder funksjonsrollen administrator. Synlighetsgrupper vedlikeholdes under «Grupper og innsyn».</p></section>`}
function appoint(){const candidates=people.filter(p=>!p.admin);if(!candidates.length){dialog('Ingen flere eksempelbrukere','<p>Alle eksempelbrukerne er allerede administratorer i skissen.</p>');return}dialog('Utnevn administrator',`<form id="appointForm">${select('Velg eksisterende bruker','person',candidates.map(p=>[p.id,p.name]),candidates[0].id)}<p>Denne personen får administratorfunksjonene i demoen. Ingen invitasjon sendes og ingen reell tilgang endres.</p><button type="submit" class="primary">Bekreft utnevnelse i skissen</button></form>`,()=>{$('appointForm').onsubmit=e=>{e.preventDefault();const p=people.find(p=>p.id===new FormData(e.target).get('person'));p.admin=true;p.source='manual';$('infoDialog').close();render();notify(p.name+' er administrator i skissen.')}})}
function connections(id){const r=rules.find(r=>r.id===id),children=dependents(r);dialog('Sammenheng: '+(r.title||r.loop),`${r.kind==='relative'?'<p>Denne regelen er <strong>avhengig</strong> av «'+esc(anchorName(r.anchor))+'». Den blir ikke selvstendig selv om andre regler følger den.</p>':'<p>Datoen beregnes selvstendig. '+(children.length?'Regelen er derfor merket som milepæl. Listen nedenfor viser direkte avhengige regler.':'Ingen regler avhenger av den.')+'</p>'}${children.length?'<ul class="dependency-list">'+children.map(c=>'<li>'+esc(c.title)+'<br><small>'+esc(sentence(c))+'</small></li>').join('')+'</ul>':''}<p>Relative regler og kjeder beregnes på nytt fra ankeret i forhåndsvisning og generering. Endring av årsmalen publiserer ingen frister.</p>`)}
function postState(){if(tab==='list'&&moduleArea==='template')updateRegister();if(!embedded||!initialized)return;parent.postMessage({type:'atelier:state',state:{rules,phases,phaseEnd,manualAnchors,people}},'*');postHeight()}
function postHeight(){if(embedded&&initialized)parent.postMessage({type:'atelier:height',height:Math.ceil($('main').getBoundingClientRect().height)+16},'*')}
document.addEventListener('input',e=>{if(e.target.name==='registerSearch'){search=e.target.value;updateRegister()}});
document.addEventListener('change',e=>{if(e.target.name==='sortOrder'){sortOrder=e.target.value;updateRegister()}if(e.target.name==='sortYear'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>=1&&n<=9999){sortYear=n;updateRegister()}}if(e.target.name==='roleFilter'){roleFilter=e.target.value;updateRegister()}if(e.target.name==='categoryFilter'){categoryFilter=[...document.querySelectorAll('[name=categoryFilter]:checked')].map(n=>n.value);updateRegister()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.listAction==='resetFilters'){search='';roleFilter='all';categoryFilter=['Budsjett','Gulbok','Regnskap'];render()}if(b.dataset.connections)connections(b.dataset.connections);if(b.dataset.previewRule){const r=rules.find(r=>r.id===b.dataset.previewRule);dialog('Eksempeldatoer: '+r.title,'<table class="preview-table"><thead><tr><th>Budsjettår</th><th>Beregnet dato</th></tr></thead><tbody>'+[2026,2027,2028,2029,2030].map(y=>'<tr><td>'+y+'</td><td>'+resultMarkup(calc(r,y))+'</td></tr>').join('')+'</tbody></table>')}
 if(b.dataset.settingTab){settingsTab=b.dataset.settingTab;render()}if(b.dataset.adminAction==='appoint')appoint();if(b.dataset.adminRemove){const p=people.find(p=>p.id===b.dataset.adminRemove);confirmAction('Fjerne administratortilgang?',esc(p.name)+' mister administratorfunksjonene i skissen. Brukeren slettes ikke.','Fjern tilgangen i skissen',()=>{p.admin=false;render();notify('Den manuelle administratortilgangen er fjernet i skissen.')})}
},true);
// Stopper den gamle navigasjonens informasjonsdialog for de to nå bygde områdene.
document.addEventListener('click',e=>{const b=e.target.closest('[data-nav]');if(!b||!['template','settings'].includes(b.dataset.nav))return;e.stopImmediatePropagation();const go=()=>{dirty=false;moduleArea=b.dataset.nav;if(embedded)parent.postMessage({type:'atelier:navigate',area:moduleArea},'*');render()};if(dirty)confirmAction('Forlate regelutkastet?','Vil du forkaste ulagrede endringer og bytte område?','Forkast og gå videre',go);else go()},true);
window.addEventListener('message',e=>{if(!embedded||e.source!==parent)return;const msg=e.data;if(msg?.type==='atelier:init'){if(msg.state){rules=clone(msg.state.rules);phases=clone(msg.state.phases);phaseEnd=msg.state.phaseEnd;manualAnchors=clone(msg.state.manualAnchors||{});people=clone(msg.state.people||people)}initialized=true;moduleArea=msg.area||'template';settingsTab=msg.settingsTab||settingsTab;render()}
 if(msg?.type==='atelier:show'){if(msg.area&&msg.area!==moduleArea)$('feedback').hidden=true;moduleArea=msg.area||'template';if(msg.tab)tab=msg.tab;if(msg.settingsTab)settingsTab=msg.settingsTab;render()}
 if(msg?.type==='atelier:compute'){const year=msg.year;parent.postMessage({type:'atelier:computed',year,results:rules.map(r=>{const c=calc(r,year);return {rule:r.id,title:r.title,loep:r.loop,category:r.category==='Gulbok'?'Gul bok':r.category,date:c.date?iso(c.date):null,precision:c.tentative?'month':'day',error:c.error||null}})},'*')}
});
const priorDialog=dialog;dialog=function(...args){priorDialog(...args);if(embedded)parent.postMessage({type:'atelier:dialog'},'*')};
if(embedded){document.body.classList.add('embedded');new ResizeObserver(postHeight).observe(document.body);parent.postMessage({type:'atelier:ready'},'*')}
render();
